{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_d4fe7b6e7be3522b83627fca", "claim_ids": ["claim_04bc8e24cf5f1d98dc062615", "claim_ad6a823271f7e74c8a91684c"], "query_ids": ["q_140"], "claims": [{"claim_id": "claim_04bc8e24cf5f1d98dc062615", "quote": "April 2025: De minimis exemptions are removed for packages under $800 from China, raising duties to 90%.", "url": "https://manlybattery.com/battery-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "De minimis exemptions are removed", "duty_rate": "90%", "effective_date": "April 2025"}}, {"claim_id": "claim_ad6a823271f7e74c8a91684c", "quote": "The extended tariff policy also includes key upstream materials essential for battery production. These include cathodes, anodes, electrolytes, and separator films.", "url": "https://manlybattery.com/battery-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "separator films"}}]}, {"pair_id": "conflict_59666e336ece0cd58f984732", "claim_ids": ["claim_04853cc6a0188f55f6d0e175", "claim_48ccb3cab78042423847ea3a"], "query_ids": ["q_144"], "claims": [{"claim_id": "claim_04853cc6a0188f55f6d0e175", "quote": "The products under the Orders are currently classifiable under Harmonized Tariff Schedule of the United States (HTSUS) subheadings 7607.11.3000, 7607.11.6000, 7607.11.9030, 7607.11.9060, 7607.11.9090, and 7607.19.6000.", "url": "https://www.federalregister.gov/documents/2023/10/02/2023-21653/certain-aluminum-foil-from-the-peoples-republic-of-china-continuation-of-antidumping-and", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"hts_code": "7607.11.3000, 7607.11.6000, 7607.11.9030, 7607.11.9060, 7607.11.9090, and 7607.19.6000"}}, {"claim_id": "claim_48ccb3cab78042423847ea3a", "quote": "The products under investigation are currently classifiable under Harmonized Tariff Schedule of the United States (HTSUS) subheadings 7607.11.3000, 7607.11.6090, 7607.11.9030, 7607.11.9060, 7607.11.9090, and 7607.19.6000.", "url": "https://content.govdelivery.com/accounts/USDHSCBP/bulletins/2a75b2c", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"hts_code": "7607.11.3000, 7607.11.6090, 7607.11.9030, 7607.11.9060, 7607.11.9090, and 7607.19.6000"}}]}, {"pair_id": "conflict_8cd079d6a3405d7b461e7c2e", "claim_ids": ["claim_1fde0113c49851106611218b", "claim_dd2cb3423f689d5e87535cf4"], "query_ids": ["q_148"], "claims": [{"claim_id": "claim_1fde0113c49851106611218b", "quote": "terf rate on battery parts will increase this year from 7.5% to 25%", "url": "https://www.youtube.com/watch?v=MFT-KOrTJOo", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "battery parts", "duty_rate": "7.5% to 25%"}}, {"claim_id": "claim_dd2cb3423f689d5e87535cf4", "quote": "Tariff rate on lithium ion EV batteries is increasing this year from 7.5% to 25%", "url": "https://www.youtube.com/watch?v=MFT-KOrTJOo", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "lithium ion EV batteries", "duty_rate": "7.5% to 25%"}}]}, {"pair_id": "conflict_8c950466ea8de592056b0d7b", "claim_ids": ["claim_094455516e5c6de27b068c9b", "claim_1ce853bb7ec29184c5ff250b"], "query_ids": ["q_149"], "claims": [{"claim_id": "claim_094455516e5c6de27b068c9b", "quote": "Machines designed to align and adhere square or rectangular monocrystalline silicon ingots (boules) of an initial mass exceeding 200 kg to plastic support boards on metal mounting plates to provide support during diamond wire sawing, for use in solar wafer manufacturing (described in statistical reporting number 8486.10.0000).", "url": "https://ustr.gov/sites/default/files/Section%20301%20Modifications%20Determination%20FRN%20(Sept%2012%202024)%20(FINAL).pdf", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Exclusions for Solar Manufacturing Equipment", "affected_product": "Machines designed to align and adhere square or rectangular monocrystalline silicon ingots (boules) of an initial mass exceeding 200 kg to plastic support boards on metal mounting plates to provide support during diamond wire sawing", "hts_code": "8486.10.0000"}}, {"claim_id": "claim_1ce853bb7ec29184c5ff250b", "quote": "Diamond wire saws designed for cutting or slicing square or rectangular monocrystalline silicon ingots (boules) of an initial mass exceeding 400 kg into solar wafers of a thickness not exceeding 200 micrometers (described in statistical reporting number 8486.10.0000).", "url": "https://www.federalregister.gov/documents/2024/09/18/2024-21217/notice-of-modification-chinas-acts-policies-and-practices-related-to-technology-transfer", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "Diamond wire saws designed for cutting or slicing square or rectangular monocrystalline silicon ingots (boules) of an initial mass exceeding 400 kg into solar wafers of a thickness not exceeding 200 micrometers", "hts_code": "8486.10.0000"}}]}, {"pair_id": "conflict_7baae0a4aa4ccdd1468a6584", "claim_ids": ["claim_2ab61f7a21621289c263dbd3", "claim_2d2b9ee759ad0e43f08f7c75"], "query_ids": ["q_149"], "claims": [{"claim_id": "claim_2ab61f7a21621289c263dbd3", "quote": "The U.S. Trade Representative determined to establish a process by which particular products classified in heading 9903.88.02 and provided for in U.S. notes 20(c) and (d) to this subchapter could be excluded from the additional duties imposed by heading 9903.88.02.", "url": "https://ustr.gov/sites/default/files/Section%20301%20Modifications%20Determination%20FRN%20(Sept%2012%202024)%20(FINAL).pdf", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "heading 9903.88.02", "legal_authority": "U.S. Trade Representative"}}, {"claim_id": "claim_2d2b9ee759ad0e43f08f7c75", "quote": "Pursuant to the product exclusion process, the U.S. Trade Representative has determined that the additional duties imposed by heading 9903.88.02 and U.S. note 20(d) to this subchapter shall not apply to the products of China described herein and classified in the specified subheadings of heading 8486 of the tariff schedule, when such products of China are entered with a claim for the tariff treatment provided in heading 9903.88.70 of this subchapter:", "url": "https://ustr.gov/sites/default/files/Section%20301%20Modifications%20Determination%20FRN%20(Sept%2012%202024)%20(FINAL).pdf", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "heading 9903.88.02", "affected_product": "products of China described herein and classified in the specified subheadings of heading 8486", "country_of_origin": "China"}}]}, {"pair_id": "conflict_49ca2d9c9f452f0213620213", "claim_ids": ["claim_037023c4288b85a36ba166e2", "claim_c6fce8e77a05612154c22bc4"], "query_ids": ["q_152"], "claims": [{"claim_id": "claim_037023c4288b85a36ba166e2", "quote": "rare earth products, including magnets, were not on the list, indicating they are exempt by omission.", "url": "https://www.adamasintel.com/us-reciprocal-tariffs-to-hit-rare-earth-magnets-upstream-products-exempt", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "10% import tariffs on China", "affected_product": "magnets"}}, {"claim_id": "claim_c6fce8e77a05612154c22bc4", "quote": "the US published an annex of exemptions, which includes REE metals, REE compounds, and mixtures thereof, but does not include neodymium-iron-boron (NdFeB) or samarium-cobalt (SmCo), suggesting the baseline 10% tariff increase from April 5th and the higher country-specific rates from April 9th will apply to rare earth permanent magnets", "url": "https://www.adamasintel.com/us-reciprocal-tariffs-to-hit-rare-earth-magnets-upstream-products-exempt", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "rare earth permanent magnets", "duty_rate": "10%", "effective_date": "April 5th"}}]}, {"pair_id": "conflict_ecd9d03855af8b5e5dd6b118", "claim_ids": ["claim_037023c4288b85a36ba166e2", "claim_9d0c30c09bf3d9c28c224363"], "query_ids": ["q_152"], "claims": [{"claim_id": "claim_037023c4288b85a36ba166e2", "quote": "rare earth products, including magnets, were not on the list, indicating they are exempt by omission.", "url": "https://www.adamasintel.com/us-reciprocal-tariffs-to-hit-rare-earth-magnets-upstream-products-exempt", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "10% import tariffs on China", "affected_product": "magnets"}}, {"claim_id": "claim_9d0c30c09bf3d9c28c224363", "quote": "Starting April 5, 2025, all countries and territories will be tariffed at a rate of 10%, over and above any existing tariffs or levies in place.", "url": "https://www.adamasintel.com/us-reciprocal-tariffs-to-hit-rare-earth-magnets-upstream-products-exempt", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "reciprocal import tariffs", "duty_rate": "10%", "announcement_date": "this week", "effective_date": "April 5, 2025"}}]}, {"pair_id": "conflict_2cd4a7f68d3f4f9b21a1d823", "claim_ids": ["claim_9d0c30c09bf3d9c28c224363", "claim_c6fce8e77a05612154c22bc4"], "query_ids": ["q_152"], "claims": [{"claim_id": "claim_9d0c30c09bf3d9c28c224363", "quote": "Starting April 5, 2025, all countries and territories will be tariffed at a rate of 10%, over and above any existing tariffs or levies in place.", "url": "https://www.adamasintel.com/us-reciprocal-tariffs-to-hit-rare-earth-magnets-upstream-products-exempt", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "reciprocal import tariffs", "duty_rate": "10%", "announcement_date": "this week", "effective_date": "April 5, 2025"}}, {"claim_id": "claim_c6fce8e77a05612154c22bc4", "quote": "the US published an annex of exemptions, which includes REE metals, REE compounds, and mixtures thereof, but does not include neodymium-iron-boron (NdFeB) or samarium-cobalt (SmCo), suggesting the baseline 10% tariff increase from April 5th and the higher country-specific rates from April 9th will apply to rare earth permanent magnets", "url": "https://www.adamasintel.com/us-reciprocal-tariffs-to-hit-rare-earth-magnets-upstream-products-exempt", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "rare earth permanent magnets", "duty_rate": "10%", "effective_date": "April 5th"}}]}, {"pair_id": "conflict_4cc337c892b63af539f46e27", "claim_ids": ["claim_36f68853e2be5e56fed5cea8", "claim_6c3f60733655cbc875361060"], "query_ids": ["q_153"], "claims": [{"claim_id": "claim_36f68853e2be5e56fed5cea8", "quote": "Magnets (8505.11 / 8505.19) get a firm +25% on 1/1/2026", "url": "https://www.duramag.com/techtalk/magnet-news/understanding-the-2026-section-301-tariffs-on-permanent-magnets-what-the-market-needs-to-know", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "Magnets", "hts_code": "8505.11 / 8505.19"}}, {"claim_id": "claim_6c3f60733655cbc875361060", "quote": "sintered neodymium-iron-boron (NdFeB) permanent magnets classified under HTS 8505.11.00.70 were explicitly excluded from the IEEPA-based “Executive Tariffs” pursuant to Annex II of the U.S.–China tariff framework.", "url": "https://www.duramag.com/techtalk/magnet-news/understanding-the-2026-section-301-tariffs-on-permanent-magnets-what-the-market-needs-to-know", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"hts_code": "8505.11.00.70"}}]}, {"pair_id": "conflict_1abddeeaef71a7960b9f40e3", "claim_ids": ["claim_2e95a57d21722a23a499a394", "claim_fb797d05d19da081fa853c3d"], "query_ids": ["q_154"], "claims": [{"claim_id": "claim_2e95a57d21722a23a499a394", "quote": "An additional 25% tariff will be applied on top of all standard duty rates and any Executive Tariffs in effect at that time. This will materially change the landed cost of nearly every commercial magnet imported from China.", "url": "https://www.duramag.com/techtalk/magnet-news/understanding-the-2026-section-301-tariffs-on-permanent-magnets-what-the-market-needs-to-know", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Dura Magnetics", "duty_rate": "25%", "effective_date": "January 1, 2026"}}, {"claim_id": "claim_fb797d05d19da081fa853c3d", "quote": "Magnets (8505.11 / 8505.19) get a firm +25% on 1/1/2026", "url": "https://www.duramag.com/techtalk/magnet-news/understanding-the-2026-section-301-tariffs-on-permanent-magnets-what-the-market-needs-to-know", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Dura Magnetics", "affected_product": "Magnets (8505.11 / 8505.19)", "duty_rate": "+25%", "effective_date": "1/1/2026"}}]}]}

